package com.brasa.restaurant.exception;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;@RestControllerAdvice public class GlobalExceptionHandler{record ErrorBody(Instant timestamp,int status,String error,String message,Map<String,String>fields){}@ExceptionHandler(ApiExceptions.NotFound.class)ResponseEntity<ErrorBody>notFound(Exception e){return body(HttpStatus.NOT_FOUND,e,Map.of());}@ExceptionHandler(ApiExceptions.Forbidden.class)ResponseEntity<ErrorBody>forbidden(Exception e){return body(HttpStatus.FORBIDDEN,e,Map.of());}@ExceptionHandler(ApiExceptions.Business.class)ResponseEntity<ErrorBody>business(Exception e){return body(HttpStatus.BAD_REQUEST,e,Map.of());}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ErrorBody>validation(MethodArgumentNotValidException e){Map<String,String>f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.put(x.getField(),x.getDefaultMessage()));return body(HttpStatus.UNPROCESSABLE_ENTITY,new RuntimeException("Dados inválidos"),f);}@ExceptionHandler(Exception.class)ResponseEntity<ErrorBody>other(Exception e){return body(HttpStatus.INTERNAL_SERVER_ERROR,new RuntimeException("Erro interno"),Map.of());}private ResponseEntity<ErrorBody>body(HttpStatus s,Exception e,Map<String,String>f){return ResponseEntity.status(s).body(new ErrorBody(Instant.now(),s.value(),s.getReasonPhrase(),e.getMessage(),f));}}
